<?php require 'admin_bootstrap.php'; $title='Important Dates'; if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=$_POST['action']??'';if($a==='add_date'){ $titleD=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$dt=$_POST['event_date']??'';$type=$_POST['event_type']??'Academic';if($titleD===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$dt))throw new Exception('Title and a valid date are required.');if(!in_array($type,['Academic','Enrollment','Exam','Holiday','Other'],true))$type='Academic';$q=$pdo->prepare('INSERT INTO important_dates(title,description,event_date,event_type,created_by) VALUES(?,?,?,?,?)');$q->execute([$titleD,$desc,$dt,$type,$_SESSION['user']['id']]);$_SESSION['admin_flash']=['msg'=>'Important date added.','error'=>''];}elseif($a==='delete_date'){ $pdo->prepare('DELETE FROM important_dates WHERE id=?')->execute([(int)$_POST['id']]);$_SESSION['admin_flash']=['msg'=>'Important date removed.','error'=>''];}}catch(Throwable $e){$_SESSION['admin_flash']=['msg'=>'','error'=>$e->getMessage()];}header('Location: admin_important_dates.php');exit;}$rows=$pdo->query('SELECT * FROM important_dates ORDER BY event_date')->fetchAll();require 'header.php';admin_flash_html();?><section class="section"><div class="section-intro"><div><span class="eyebrow">ADMINISTRATION</span><h2>Important Dates</h2><p class="muted">Manage upcoming academic dates visible to users.</p></div></div><form class="date-admin-form" method="post"><input type="hidden" name="action" value="add_date"><input required name="title" placeholder="Event title"><input name="description" placeholder="Description"><input required type="date" name="event_date" min="<?=date('Y-m-d')?>"><select name="event_type"><option>Academic</option><option>Enrollment</option><option>Exam</option><option>Holiday</option><option>Other</option></select><button class="btn">Add Date</button></form><div class="table-scroll"><table class="table"><tr><th>Date</th><th>Title</th><th>Type</th><th>Description</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=date('M d, Y',strtotime($r['event_date']))?></td><td><b><?=e($r['title'])?></b></td><td><?=e($r['event_type'])?></td><td><?=e($r['description']?:'—')?></td><td><form method="post"><input type="hidden" name="action" value="delete_date"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger-btn" onclick="return confirm('Remove this date?')">Remove</button></form></td></tr><?php endforeach;?></table></div></section><?php require 'footer.php'; ?>
